const code=await readFile(new URL('../operator-ui/review.js',import.meta.url),'utf8');
class Element{
 constructor(tag='div',text=''){this.tagName=tag;this.textContent=text;this.children=[];this.value='all';this.hidden=false;this.dataset={};this.attributes={};this.events={};}
 prepend(...nodes){this.children.unshift(...nodes);} focus(){} querySelector(tag){return this.children.find(n=>n.tagName===tag)||null;}
 append(...nodes){this.children.push(...nodes);} replaceChildren(...nodes){this.children=[...nodes];} add(n){if(this.tagName==='select'&&!this.children.length)this.value=n.value;this.append(n);} checkValidity(){return !this.required||!!this.value;} get options(){return this.children;}
 setAttribute(k,v){this.attributes[k]=v;} addEventListener(k,f){this.events[k]=f;} querySelectorAll(){return [];} showModal(){this.open=true;} close(){this.open=false;}
}
const row=(id,valid,errors=[],facts={product:id})=>({id,label:id,source:'Source',sourceId:'source',decision:'PUBLISH_REVIEW',sourceUrl:'https://example.com/'+id,status:'pending',facts,history:[],validation:{valid,errors,duplicates:[],quality:{labelInformationScore:1},publishableLabel:id}});
function ui(rows,fixture={}){const ids=Object.fromEntries(['preparation-exceptions','preparation-exceptions-load','assisted-entry','assisted-fields','assisted-status','published-day','published-list','presentation-save','presentation-reset','presentation-status','review-workspace','published-workspace','tab-review','tab-published','mode','source','count','list','notice','submit','retry','checks','reload','identity','confirm','confirm-title','confirm-label','reason','dashboard','human-history','history-list','history-more','shadow-summary','shadow-evaluate','shadow-pattern-list','last-updated','refresh-status','rejected-count','parser-diagnostics'].map(id=>[id,new Element()]));const requests=[];const context=vm.createContext({...(fixture.location?{location:{href:fixture.location}}:{}),document:{getElementById:id=>ids[id],createElement:tag=>new Element(tag),createTextNode:text=>new Element('#text',text)},URL,Option:class extends Element{constructor(t,v){super('option',t);this.value=v;}},sessionStorage:fixture.storage||{getItem:()=>null,setItem:()=>{}},fetch:async(path,options)=>{requests.push({path,options});return {ok:true,json:async()=>path==='/api/assisted-draft'?fixture.draftReply:path.startsWith('/api/assisted')?(fixture.config||{sources:[{id:'yamaha',name:'ヤマハ'}],types:{acoustic_guitar:['アコギ','acoustic_guitar']},actions:{announcement:'発表'}}):path==='/api/session'?{operator:'test',version:'0.16.0'}:path==='/api/summary'?{published:53,pending:rows.length,rejected:19,humanDecisions:2}:path==='/api/shadow-metrics'?{totalHumanDecisions:2,independentHumanDecisions:0,unmatchedHumanDecisions:2,evaluationsRecorded:0,observations:{},patterns:[],lowSample:true}:path.startsWith('/api/human-decisions')?{items:[],nextOffset:null}:{items:rows}}},crypto:{randomUUID:()=> 'test'},console});vm.runInContext(code,context);return {ids,requests,context,run:s=>vm.runInContext(s,context)};}
const settle=()=>new Promise(resolve=>setImmediate(resolve));
test('opening a prepared draft prefills all fields with no confirmation/save; revisions discard a stale generated headline',async()=>{
 const url='https://www.yamaha.com/ja/news_release/2026/26110601/',fields={url,sourceId:'yamaha-newsroom',brand:'ヤマハ',product:'Acompass 60',productType:'guitar_amp',action:'announcement',publishedAt:'2026-11-06',label:'ヤマハ、ギターアンプ「Acompass 60」を発表'};
 const information={version:1,url,source:{label:'運営者の確認用情報',url},fields:{publishedAt:'2026-11-06'}};
 const draft={registrationAllowed:true,fields,headline:fields.label,fieldSources:{label:{kind:'generated_from_draft'},publishedAt:{kind:'provided_information'}},notes:[{label:'発売予定',value:'2026年12月上旬'}],assistanceSource:information.source};
 const config={sources:[{id:'yamaha-newsroom',name:'ヤマハ',basis:'public_facts_conditions_review'}],types:{guitar_amp:['ギターアンプ','amps_effects']},actions:{announcement:'を発表'},draft:{...draft,headline:'元のAI案',fields:{...fields,publishedAt:'',action:'release'}}};
 const u=ui([],{location:'https://operator.test/?assistedUrl='+encodeURIComponent(url)+'#assistedDraft='+encodeURIComponent(JSON.stringify(information)),config,draftReply:{draft,readOnly:true}});await settle();await settle();
 for(const [k,v]of Object.entries(fields))assert.equal(u.run('assistedInputs['+JSON.stringify(k)+'].value'),v);
 assert.equal(u.run('assistedConfirm.checked===true||assistedConditions.checked===true'),false);assert.equal(u.run('assistedSave.disabled'),true);
 assert(u.requests.some(r=>r.path==='/api/assisted-draft'&&r.options.method==='POST'));assert(!u.requests.some(r=>/assisted-save|assisted-preview|\/decision/.test(r.path)));
 assert.equal(u.run('assistedProposal.hidden'),false);assert.equal(u.run('assistedProposal.querySelector("h3").textContent'),fields.label);
 u.run('assistedInputs.product.value="CORRECTED-200";assistedInputs.product.events.input()');assert.equal(u.run('assistedInputs.label.value'),'');assert.equal(u.run('assistedSave.disabled'),true);
 u.run('assistedNew.events.click()');assert.equal(u.run('assistedProposal.hidden'),true);
});
